import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const file=p=>readFileSync(p,'utf8');
const page=file('app/page.tsx');
const impact=file('app/components/GreenOrderImpact.tsx');
const orderApi=file('app/api/green/orders/[id]/route.ts');
const green=file('app/green/page.tsx');
const docs=file('docs/ZESHU_GREEN_TREE_PROGRAM.md');
const translations=file('app/components/CustomerLanguageProvider.tsx');

assert(page.includes('<GreenOrderImpact />'));
assert(page.includes('<GreenOrderImpact orderId={trackedOrder.id} orderStatus={trackedOrder.status} />'));
assert(impact.includes("fetch('/api/green/impact',{cache:'no-store'})"));
assert(impact.includes('customerSupabase().auth.getSession()'));
assert(impact.includes("Authorization:'Bearer '+session.access_token"));
assert(!impact.includes('role="progressbar"'));
assert(!impact.includes('{w.milestone}')&&!impact.includes('{w.explain}'));
assert(impact.includes('if(!orderId)return <section data-green-impact="cart"'));
assert(impact.includes('flex items-center gap-2.5 rounded-xl')&&impact.includes('px-3 py-2.5'));
const compact=impact.split('if(!orderId)return <section data-green-impact="cart"')[1]?.split('return <section data-green-impact="order"')[0]||'';
assert(compact.includes('{words.name}')&&compact.includes('{description}'));
assert(!compact.includes('href="/green"')&&!compact.includes('words.goal'));
assert(!compact.includes('one tree planted')&&!compact.includes('contributed to planting'));
assert(impact.includes('Your shopping helps Zeshu move toward planting trees.'));
assert(impact.includes('No tree is planted or reserved for this order.'));
assert(!impact.includes('Our goal: 1 tree per eligible delivered order.'));
assert(!impact.includes('One tree planted, thanks to your order!'));
for(const locale of ['en','te','hi','ur'])assert(impact.includes(locale+':{'));
assert(impact.includes("impact?.status==='VERIFIED'&&impact.proofUrl"));
assert(impact.includes('No extra fee'));
assert(orderApi.includes('customer.auth.getUser(access)'));
assert(orderApi.includes(".eq('id',id).eq('user_id',user.id)"));
assert(orderApi.includes("db.from('zeshu_green_tree_commitments')"));
assert(orderApi.includes("status==='VERIFIED'"));
assert(orderApi.includes('feePaise:0'));
assert(!orderApi.includes('export async function POST'));
assert(!orderApi.includes('insert(')&&!orderApi.includes('update('));
assert(green.includes('First 1,000 eligible delivered orders'));
assert(docs.includes('No extra fee'));
assert(translations.split('"Payment receipt and order summary"').length>=4);
console.log('PASS: two-line Green cart, truthful post-order status and private verified-only evidence; no one-tree-per-order claim.');
